package com.bank.state;

import java.math.BigDecimal;
import java.util.logging.*;

public class StaticVsInstanceDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000.00"));

        log.info(() -> "Accounts opened so far = " + Account.getAccountsOpened()); // shared = 2

        // Mutating Rajesh's INSTANCE balance does NOT affect Priya's.
        rajesh.debit(new BigDecimal("50000"));
        log.info(() -> "Rajesh balance = " + rajesh.getBalance()); // 950000
        log.info(() -> "Priya  balance = " + priya.getBalance());  // 250000 unchanged

        // Opening a third account increments the SHARED static counter.
        Account newCust = new Account("SAV2002", "Amit Verma", new BigDecimal("5000.00"));
        log.info(() -> "Accounts opened so far = " + Account.getAccountsOpened()); // shared = 3
    }
}

// ─── Would be Account.java in a real project ───
class Account {
    // static VARIABLE: one shared copy for the whole class
    private static int accountsOpened = 0;

    // INSTANCE variables: a separate copy per object
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;

    Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
        accountsOpened++; // mutate SHARED static state once per new object
    }

    String getAccountId() { return accountId; }
    BigDecimal getBalance() { return balance; }
    void debit(BigDecimal a) { balance = balance.subtract(a); }   // affects THIS object only
    void credit(BigDecimal a) { balance = balance.add(a); }

    static int getAccountsOpened() { return accountsOpened; }      // class-level accessor
}
